('alict_01951', 12, 'General ICT', 'Which of the following is a key challenge that must be addressed with rise of quantum computing in ICT?', '["Increased energy consumption", "Security vulnerabilities due to faster decryption methods", "Reduced computing power compared to classical computers", "Incompatibility with current programming languages", "Limited storage capacity for quantum bits"]'::jsonb, 2, 'Option 1: Quantum computing is not known for significantly higher energy consumption compared to classical computers. The technology is still and energy efficiency is a concern but not a primary challenge at this stage. Option 2: This is a key challenge posed by quantum computing', NULL, NULL, 'medium', 'General ICT', NULL, 1951, 'A/L Past Paper Series'),
('alict_01952', 12, 'General ICT', 'Which of the following is not a key property of agent technology?', '["Working in a dynamic environment", "Intelligence", "Self-execution", "Sales promotion", "Competing with other agents"]'::jsonb, 4, 'Correct answer: "Sales promotion".', NULL, NULL, 'medium', 'General ICT', NULL, 1952, 'A/L Past Paper Series'),
('alict_01953', 12, 'General ICT', 'A smart home app that controls entertainment systems and appliances is an example of which of the following?', '["Software Agent", "Evolutionary Computing", "Universal computing", "Multi-Agent Systems", "Computing inspired by nature"]'::jsonb, 3, 'In the context of a smart home app that controls various systems and appliances), universal computing refers to the concept of using computers and software to universally manage and integrate different functions and systems in a seamless manner', NULL, NULL, 'medium', 'General ICT', NULL, 1953, 'A/L Past Paper Series'),
('alict_01954', 12, 'General ICT', 'What type of testing is done before the client accepts a system?', '["Unit testing", "Integrated testing", "Acceptance testing", "System testing", "White box testing"]'::jsonb, 3, 'Unit testing • Purpose To verify that individual components or units of code work as intended. • Scope Focuses on the smallest parts of an such as functions or methods. • Performed By Typically conducted by developers', NULL, NULL, 'medium', 'General ICT', NULL, 1954, 'A/L Past Paper Series'),
('alict_01955', 12, 'General ICT', 'Which of the following is a biometric method of authentication?', '["Username and password", "Access tokens", "Smart cards", "Security questions", "Fingerprint scanning"]'::jsonb, 5, 'The correct biometric method of authentication is fingerprint scanning (Option 5), as it uses a person''s unique biological characteristic for identification', NULL, NULL, 'medium', 'General ICT', NULL, 1955, 'A/L Past Paper Series'),
('alict_01956', 12, 'General ICT', 'Which of the following is an example of a secure payment mechanism?', '["Payment gateways", "Open-source payment methods", "Manual bank transfers", "Unverified wire transfers", "Crowdfunding platforms"]'::jsonb, 1, 'Payment gateways Payment gateways are considered secure because they encrypt sensitive payment such as credit card ensuring that the transaction is safe and protecting against fraud', NULL, NULL, 'medium', 'General ICT', NULL, 1956, 'A/L Past Paper Series'),
('alict_01957', 12, 'General ICT', 'What type of business organization does a website like E-bay belong to?', '["Pure brick", "Pure Click", "Brick and Click", "C2C", "B2B"]'::jsonb, 3, 'Correct answer: "Brick and Click".', NULL, NULL, 'medium', 'General ICT', NULL, 1957, 'A/L Past Paper Series'),
('alict_01958', 12, 'General ICT', 'In a multi-agent how do agents typically interact?', '["By ignoring each other and working independently", "By continuously communicating and coordinating tasks within their environment. Tjqkaf.a", "By performing identical tasks without any collaboration", "By requiring constant external control to interact", "By following a hierarchical command structure only"]'::jsonb, 2, 'Option 1: Agents work which isn''t typical in multi-agent systems. nyq Option 2: Agents share information and coordinate tasks to achieve goals. Option 3: Agents work in parallel without which isn''t efficient. Option 4: Limits agent reducing effectiveness', NULL, NULL, 'medium', 'General ICT', NULL, 1958, 'A/L Past Paper Series'),
('alict_01959', 12, 'General ICT', 'What is a non-functional requirement of a refrigerator?', '["Must be able to cool food", "Must be able to preserve food", "Harmful gases like CFC should not be released", "The freshness of the food must be preserved", "Must be able to create ice cubes"]'::jsonb, 3, 'Correct answer: "Harmful gases like CFC should not be released".', NULL, NULL, 'medium', 'General ICT', NULL, 1959, 'A/L Past Paper Series'),
